[CmdletBinding()] param([Parameter(Mandatory)][string]$SourceRoot,[Parameter(Mandatory)][string]$OutputPath,[string]$GeneratedUtc=[DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ'))
$ErrorActionPreference='Stop'; Import-Module (Join-Path $PSScriptRoot 'modules\SourceInventory.psm1') -Force; $inventory=Get-ArchitectureSourceInventory -SourceRoot $SourceRoot -GeneratedUtc $GeneratedUtc; $json=$inventory|ConvertTo-Json -Depth 6; if([IO.Path]::IsPathRooted($OutputPath)){$absoluteOutput=[IO.Path]::GetFullPath($OutputPath)}else{$absoluteOutput=[IO.Path]::GetFullPath((Join-Path (Get-Location) $OutputPath))}; $parent=Split-Path -Parent $absoluteOutput; if(-not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null}; [IO.File]::WriteAllText($absoluteOutput,$json+"`n",[Text.UTF8Encoding]::new($false)); Write-Output "Wrote source inventory: $OutputPath"